"use client";

import { useState, useMemo, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
  Calendar,
  ChevronLeft,
  ChevronRight,
  ClipboardList,
  Clock,
  Gavel,
  AlertTriangle,
  List,
  Plus,
  Grid3X3,
  CheckCircle2
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from "@/components/ui/dialog";
import { cn, daysUntil } from "@/lib/utils";
import type { ScheduleItem } from "@/server/schedule/query";
import { procedureTypeLabel } from "@/lib/enums";
import { AddTaskDialog } from "./add-task-dialog";
import { matterHref } from "@/lib/matters/route";

const typeMeta = {
  hearing: { icon: Gavel, label: "Audiencia", color: "#5B8DEF" },
  deadline: { icon: AlertTriangle, label: "Vencimiento", color: "#FBBF24" },
  task: { icon: ClipboardList, label: "Tarea", color: "#4FD1C5" }
} as const;

const WEEKDAY_LABELS = ["L", "Ma", "Mi", "J", "V", "S", "D"];
const VISIBLE_ITEMS_PER_DAY = 4;

export function ScheduleView({
  items,
  matters,
  users
}: {
  items: ScheduleItem[];
  matters: { id: string; internalCode: string; title: string }[];
  users?: { id: string; name: string; role: string }[];
}) {
  const router = useRouter();
  const [view, setView] = useState<"list" | "calendar">("calendar");
  const [monthOffset, setMonthOffset] = useState(0);

  const [detailItem, setDetailItem] = useState<ScheduleItem | null>(null);
  const [addOpen, setAddOpen] = useState(false);
  const [addDate, setAddDate] = useState<Date | null>(null);

  // Estado local para eliminar tareas visualmente sin recargar
  const [hiddenIds, setHiddenIds] = useState<Set<string>>(new Set());

  // today calculado solo en el cliente para evitar hidratación inconsistente
  const [today, setToday] = useState<Date>(() => {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  });

  useEffect(() => {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    setToday(d);
  }, []);

  const itemsWithDate = useMemo(
    () =>
      items
        .filter((it) => !hiddenIds.has(it.id))
        .map((it) => ({
          ...it,
          dateKey: dateKey(new Date(it.occurredAt))
        })),
    [items, hiddenIds]
  );

  const weekEnd = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);

  function openAddDialog(date?: Date | null) {
    setAddDate(date ?? today);
    setAddOpen(true);
  }

  const stats = useMemo(() => {
    const todayCount = itemsWithDate.filter(
      (it) => it.dateKey === dateKey(today)
    ).length;
    const weekCount = itemsWithDate.filter((it) => {
      const d = new Date(it.occurredAt);
      return d >= today && d < weekEnd;
    }).length;
    const hearingCount = items.filter((it) => it.type === "hearing").length;
    const deadlineCount = items.filter((it) => it.type === "deadline").length;
    return { todayCount, weekCount, hearingCount, deadlineCount };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemsWithDate]);

  return (
    <div className="space-y-4">
      <header className="ll-page-head">
        <div>
          <h1 className="ll-page-title">Calendario</h1>
          <p className="ll-page-sub">Próximos 90 días de audiencias, vencimientos y tareas pendientes</p>
        </div>

          <div className="flex flex-wrap items-center justify-end gap-2">
            <Button size="sm" onClick={() => openAddDialog()} className="h-8 gap-1.5">
              <Plus className="h-3.5 w-3.5" strokeWidth={1.8} />
              Agregar al calendario
            </Button>
            <div
              className="ll-segmented"
            >
              <button
                type="button"
                onClick={() => setView("list")}
                className={cn("ll-seg", view === "list" && "ll-seg-active text-primary")}
              >
                <List className="h-3.5 w-3.5" strokeWidth={1.8} />
                Lista
              </button>
              <button
                type="button"
                onClick={() => setView("calendar")}
                className={cn("ll-seg", view === "calendar" && "ll-seg-active text-primary")}
              >
                <Grid3X3 className="h-3.5 w-3.5" strokeWidth={1.8} />
                Mes
              </button>
            </div>
          </div>
      </header>

      {/* KPI */}
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Stat label="Hoy" value={stats.todayCount} color="hsl(var(--primary))" icon={<Clock className="h-3.5 w-3.5" />} />
        <Stat label="Esta semana" value={stats.weekCount} color="#4FD1C5" icon={<Calendar className="h-3.5 w-3.5" />} />
        <Stat label="Audiencias" value={stats.hearingCount} color="hsl(var(--primary))" icon={<Gavel className="h-3.5 w-3.5" />} />
        <Stat label="Vencimientos" value={stats.deadlineCount} color="#EA580C" icon={<AlertTriangle className="h-3.5 w-3.5" />} />
      </div>

      {view === "list" ? (
        <ListView items={itemsWithDate} today={today} />
      ) : (
        <CalendarView
          items={itemsWithDate}
          monthOffset={monthOffset}
          onOffsetChange={setMonthOffset}
          onSelectItem={setDetailItem}
          onAddDay={openAddDialog}
        />
      )}
      <ScheduleItemDialog
        item={detailItem}
        onOpenChange={(open) => !open && setDetailItem(null)}
        onTaskCompleted={(id) => setHiddenIds((prev) => new Set(prev).add(id))}
        router={router}
      />
      <AddTaskDialog
        open={addOpen}
        onOpenChange={setAddOpen}
        date={addDate}
        matters={matters}
        users={users}
      />
    </div>
  );
}

function ListView({
  items,
  today
}: {
  items: (ScheduleItem & { dateKey: string })[];
  today: Date;
}) {
  // Agrupar por día
  const groups = useMemo(() => {
    const map = new Map<string, (ScheduleItem & { dateKey: string })[]>();
    for (const it of items) {
      if (!map.has(it.dateKey)) map.set(it.dateKey, []);
      map.get(it.dateKey)!.push(it);
    }
    return Array.from(map.entries()).sort(([a], [b]) => a.localeCompare(b));
  }, [items]);

  if (items.length === 0) {
    return (
      <div className="ll-surface border-dashed py-16 text-center">
        <p className="text-sm text-muted-foreground">No hay eventos en los próximos 90 días</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {groups.map(([key, group]) => {
        const d = new Date(key);
        const isToday = key === dateKey(today);
        const days = daysUntil(d);
        return (
          <section
            key={key}
            className="ll-surface overflow-hidden"
          >
            <header
              className={cn(
                "ll-panel-head",
                isToday && "bg-accent"
              )}
            >
              <div className="flex items-center gap-3">
                <span className={cn("text-base font-semibold", isToday && "text-primary")}>
                  {d.toLocaleDateString("es-AR", { month: "long", day: "numeric" })}
                </span>
                <span className="text-xs text-muted-foreground">
                  {d.toLocaleDateString("es-AR", { weekday: "long" })}
                </span>
                {isToday ? (
                  <Badge className="bg-primary text-primary-foreground text-[10px]">Hoy</Badge>
                ) : (
                  <span className="text-xs text-muted-foreground">
                    {days === 1 ? "Mañana" : days > 0 ? `En ${days} días` : `Hace ${-days} días`}
                  </span>
                )}
              </div>
              <span className="font-mono text-xs tabular text-muted-foreground">
                {group.length} ítems
              </span>
            </header>
            <ul className="divide-y divide-border">
              {group.map((it) => (
                <Row key={it.id} item={it} />
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

function Row({ item }: { item: ScheduleItem }) {
  const meta = typeMeta[item.type];
  const Icon = meta.icon;
  const time = formatTime(item.occurredAt);
  const subject = displaySubject(item);

  return (
    <li className="px-5 py-3 transition-colors hover:bg-popover">
      <Link href={matterHref(item.matter)} className="flex items-start gap-3">
        <span className="w-12 shrink-0 font-mono text-sm tabular text-muted-foreground">
          {time}
        </span>
        <Icon className="mt-0.5 h-4 w-4 shrink-0" style={{ color: meta.color }} />
        <div className="flex-1 overflow-hidden">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium">{item.title}</span>
            <Badge variant="outline" className="text-[9px]" style={{ borderColor: `${meta.color}50`, color: meta.color }}>
              {meta.label}
            </Badge>
          </div>
          <div className="mt-0.5 flex items-center gap-2 text-[11px] text-muted-foreground">
            <span className={cn(item.clientName ? "" : "font-mono")}>{subject}</span>
            {item.procedureLabel && (
              <>
                <span>·</span>
                <span>
                  {procedureTypeLabel[item.procedureLabel as keyof typeof procedureTypeLabel] ??
                    item.procedureLabel}
                </span>
              </>
            )}
          </div>
        </div>
      </Link>
    </li>
  );
}

function CalendarCellItem({
  item,
  onSelect
}: {
  item: ScheduleItem;
  onSelect: (item: ScheduleItem) => void;
}) {
  const meta = typeMeta[item.type];
  const color = meta.color;
  const subject = displaySubject(item);

  return (
    <button
      type="button"
      onClick={(event) => {
        event.stopPropagation();
        onSelect(item);
      }}
      title={`${meta.label}: ${formatTime(item.occurredAt)} ${item.title} · ${subject}`}
      className={cn(
        "flex min-w-0 items-center gap-1 rounded-sm border px-1 py-0.5 text-left text-[10px] leading-4 transition-colors hover:border-current",
        item.completed && "line-through opacity-50"
      )}
      style={{ backgroundColor: `${color}16`, borderColor: `${color}45` }}
    >
      <span
        className="shrink-0 rounded-[3px] px-1 text-[9px] font-medium"
        style={{ backgroundColor: `${color}22`, color }}
      >
        {meta.label}
      </span>
      <span className="shrink-0 font-mono text-[9.5px] tabular" style={{ color }}>
        {formatTime(item.occurredAt)}
      </span>
      <span className="min-w-0 flex-1 truncate text-foreground/85">
        {item.title}
        {subject ? <span className="text-muted-foreground"> · {subject}</span> : null}
      </span>
    </button>
  );
}

function CalendarView({
  items,
  monthOffset,
  onOffsetChange,
  onSelectItem,
  onAddDay
}: {
  items: (ScheduleItem & { dateKey: string })[];
  monthOffset: number;
  onOffsetChange: (n: number) => void;
  onSelectItem: (item: ScheduleItem) => void;
  onAddDay: (date: Date) => void;
}) {
  const now = new Date();
  const cursor = new Date(now.getFullYear(), now.getMonth() + monthOffset, 1);
  const year = cursor.getFullYear();
  const month = cursor.getMonth();

  // Cuántos días tiene el mes
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  // Primer día del mes (Lunes=1 ... Domingo=7, convertido a 0-6 para que "Lunes esté más a la izquierda")
  const firstWeekday = ((new Date(year, month, 1).getDay() + 6) % 7); // 0=Lunes

  const cells: { date: Date | null; key: string | null }[] = [];
  for (let i = 0; i < firstWeekday; i++) cells.push({ date: null, key: null });
  for (let day = 1; day <= daysInMonth; day++) {
    const d = new Date(year, month, day);
    cells.push({ date: d, key: dateKey(d) });
  }
  // Completar hasta 6 filas = 42 celdas
  while (cells.length < 42) cells.push({ date: null, key: null });

  // Agrupar items por key
  const itemsByKey = useMemo(() => {
    const map = new Map<string, (ScheduleItem & { dateKey: string })[]>();
    for (const it of items) {
      if (!map.has(it.dateKey)) map.set(it.dateKey, []);
      map.get(it.dateKey)!.push(it);
    }
    return map;
  }, [items]);

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayKey = dateKey(today);

  const todayItems = [...(itemsByKey.get(todayKey) ?? [])].sort(
    (a, b) => new Date(a.occurredAt).getTime() - new Date(b.occurredAt).getTime()
  );
  const upcomingDeadlines = items
    .filter((item) => item.type === "deadline" && new Date(item.occurredAt) >= today)
    .sort((a, b) => new Date(a.occurredAt).getTime() - new Date(b.occurredAt).getTime())
    .slice(0, 6);

  return (
    <div className="grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1fr)_280px]">
      <section className="ll-surface p-4">
        <header className="mb-3 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => onOffsetChange(monthOffset - 1)}
              className="h-7 w-7 p-0"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <span className="text-base font-semibold tabular">
              {year} / {month + 1}
            </span>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => onOffsetChange(monthOffset + 1)}
              className="h-7 w-7 p-0"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
          {monthOffset !== 0 && (
            <Button variant="outline" size="sm" onClick={() => onOffsetChange(0)} className="h-7 text-xs">
              Volver a este mes
            </Button>
          )}
        </header>

      <div className="grid grid-cols-7 gap-1.5">
        {WEEKDAY_LABELS.map((w) => (
          <div
            key={w}
            className="py-1.5 text-center text-[10px] uppercase tracking-wider text-muted-foreground"
          >
            {w}
          </div>
        ))}
        {cells.map((cell, idx) => {
          if (!cell.date || !cell.key) {
            return (
              <div
                key={idx}
                className="min-h-[8rem] rounded-md border border-transparent sm:min-h-[9rem]"
              />
            );
          }
          const dayItems = itemsByKey.get(cell.key) ?? [];
          const visibleItems = dayItems.slice(0, VISIBLE_ITEMS_PER_DAY);
          const isToday = cell.key === todayKey;

          return (
            <div
              key={idx}
              className={cn(
                "group flex min-h-[8rem] flex-col rounded-md border p-1.5 text-left transition-colors sm:min-h-[9rem]",
                "border-border bg-card hover:border-input hover:bg-muted/35",
                isToday && "border-primary/40"
              )}
            >
              <div className="flex items-center justify-between gap-1">
                <span
                  className={cn(
                    "font-mono text-xs tabular",
                    isToday ? "font-semibold text-primary" : "text-foreground/80"
                  )}
                >
                  {cell.date.getDate()}
                </span>
                <button
                  type="button"
                  onClick={(event) => {
                    event.stopPropagation();
                    onAddDay(cell.date!);
                  }}
                  className="h-5 w-5 rounded-sm p-0 text-muted-foreground opacity-0 transition-opacity hover:bg-muted hover:text-primary group-hover:opacity-100 group-focus-within:opacity-100"
                  aria-label={`Agregar evento el ${cell.date.getDate()}/${month + 1}`}
                  title="Agregar al calendario"
                >
                  <Plus className="mx-auto h-3 w-3" />
                </button>
              </div>
              <div className="mt-1 flex min-h-0 flex-1 flex-col gap-1 overflow-hidden">
                {visibleItems.map((it) => (
                  <CalendarCellItem key={it.id} item={it} onSelect={onSelectItem} />
                ))}
                {dayItems.length > VISIBLE_ITEMS_PER_DAY && (
                  <span className="px-1 text-[10px] font-medium text-muted-foreground">
                    +{dayItems.length - VISIBLE_ITEMS_PER_DAY}
                  </span>
                )}
              </div>
            </div>
          );
        })}
      </div>
      </section>
      <ScheduleSideRail
        todayItems={todayItems}
        upcomingDeadlines={upcomingDeadlines}
        onSelectItem={onSelectItem}
      />
    </div>
  );
}

function ScheduleSideRail({
  todayItems,
  upcomingDeadlines,
  onSelectItem
}: {
  todayItems: (ScheduleItem & { dateKey: string })[];
  upcomingDeadlines: (ScheduleItem & { dateKey: string })[];
  onSelectItem: (item: ScheduleItem) => void;
}) {
  return (
    <aside className="space-y-4 xl:sticky xl:top-16">
      <section className="ll-surface overflow-hidden">
        <header className="ll-panel-head">
          <h3 className="ll-panel-title">
            <span className="h-2 w-2 rounded-full bg-primary" />
            Hoy
          </h3>
          <span className="font-mono text-xs text-muted-foreground tabular">
            {todayItems.length} ítems
          </span>
        </header>
        {todayItems.length === 0 ? (
          <p className="px-4 py-8 text-center text-xs text-muted-foreground">No hay eventos hoy</p>
        ) : (
          <ul className="divide-y divide-border px-4">
            {todayItems.map((item) => (
              <ScheduleSideItem key={item.id} item={item} onSelectItem={onSelectItem} showDate={false} />
            ))}
          </ul>
        )}
      </section>

      <section className="ll-surface overflow-hidden">
        <header className="ll-panel-head">
          <h3 className="ll-panel-title">
            <span className="h-2 w-2 rounded-full bg-red-500" />
            Próximos a vencer
          </h3>
          <span className="font-mono text-xs text-muted-foreground tabular">
            {upcomingDeadlines.length} ítems
          </span>
        </header>
        {upcomingDeadlines.length === 0 ? (
          <p className="px-4 py-8 text-center text-xs text-muted-foreground">No hay tareas próximas a vencer</p>
        ) : (
          <ul className="divide-y divide-border px-4">
            {upcomingDeadlines.map((item) => (
              <ScheduleSideItem key={item.id} item={item} onSelectItem={onSelectItem} showDate />
            ))}
          </ul>
        )}
      </section>
    </aside>
  );
}

function ScheduleSideItem({
  item,
  onSelectItem,
  showDate
}: {
  item: ScheduleItem;
  onSelectItem: (item: ScheduleItem) => void;
  showDate: boolean;
}) {
  const meta = typeMeta[item.type];
  const Icon = meta.icon;
  const subject = displaySubject(item);

  return (
    <li className="py-3">
      <button
        type="button"
        onClick={() => onSelectItem(item)}
        className="flex w-full min-w-0 gap-3 rounded-sm text-left transition-colors hover:text-primary"
      >
        <span
          className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-sm"
          style={{ backgroundColor: `${meta.color}18`, color: meta.color }}
        >
          <Icon className="h-3.5 w-3.5" />
        </span>
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-2">
            <span className="font-mono text-[11px] tabular text-muted-foreground">
              {showDate ? formatMonthDay(item.occurredAt) : formatTime(item.occurredAt)}
            </span>
            <span className="truncate text-[13px] font-medium">{item.title}</span>
          </span>
          <span className="mt-0.5 block truncate text-[11px] text-muted-foreground">
            {subject}
            {item.procedureLabel ? ` · ${formatProcedureLabel(item.procedureLabel)}` : ""}
          </span>
        </span>
      </button>
    </li>
  );
}

function ScheduleItemDialog({
  item,
  onOpenChange,
  onTaskCompleted,
  router
}: {
  item: ScheduleItem | null;
  onOpenChange: (open: boolean) => void;
  onTaskCompleted: (id: string) => void;
  router: ReturnType<typeof useRouter>;
}) {
  const open = Boolean(item);
  const meta = item ? typeMeta[item.type] : typeMeta.task;
  const Icon = meta.icon;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        {item && (
          <>
            <DialogHeader>
              <div className="mb-2 flex items-center gap-2">
                <span
                  className="rounded-md p-1.5"
                  style={{ backgroundColor: `${meta.color}18`, color: meta.color }}
                >
                  <Icon className="h-4 w-4" />
                </span>
                <Badge
                  variant="outline"
                  className="text-[10px]"
                  style={{ borderColor: `${meta.color}55`, color: meta.color }}
                >
                  {meta.label}
                </Badge>
                {item.completed && (
                  <Badge variant="secondary" className="text-[10px]">
                    Completado
                  </Badge>
                )}
              </div>
              <DialogTitle className="text-base leading-6">{item.title}</DialogTitle>
            </DialogHeader>

            <div className="space-y-2 rounded-lg border border-border bg-muted/20 p-3">
              <DetailLine label="Hora" value={`${formatFullDate(item.occurredAt)} ${formatTime(item.occurredAt)}`} />
              <DetailLine label="Cliente" value={item.clientName ?? "Cliente sin completar"} />
              <DetailLine
                label="Caso asociado"
                value={
                  <Link
                    href={matterHref(item.matter)}
                    className="font-medium text-primary underline-offset-4 hover:underline"
                  >
                    {item.matter.title}
                  </Link>
                }
              />
              {item.procedureLabel && (
                <DetailLine label="Procedimiento" value={formatProcedureLabel(item.procedureLabel)} />
              )}
              {item.type === "deadline" && item.category && (
                <DetailLine label="Tipo de vencimiento" value={item.category} />
              )}
              {item.type === "deadline" && item.remindDays !== undefined && (
                <DetailLine label="Recordatorio" value={`Con ${item.remindDays} días de anticipación`} />
              )}
              {item.type === "task" && item.priority !== undefined && (
                <DetailLine label="Prioridad" value={priorityLabel(item.priority)} />
              )}
              {item.description && (
                <div className="space-y-1 border-t border-border pt-2">
                  <div className="text-[11px] text-muted-foreground">Detalle</div>
                  <p className="whitespace-pre-wrap text-sm leading-6">{item.description}</p>
                </div>
              )}
            </div>

            <DialogFooter className="gap-2">
              <Button variant="outline" onClick={() => onOpenChange(false)}>
                Cerrar
              </Button>
              {item.type === "task" && !item.completed && (
                <Button
                  onClick={async () => {
                    try {
                      const taskId = item.id.replace(/^t-/, "");
                      const { toggleTaskCompleted } = await import("@/server/tasks/actions");
                      const result = await toggleTaskCompleted(taskId);
                      if (result.ok) {
                        // Ocultar la tarea del UI sin recargar
                        onTaskCompleted(item.id);
                        onOpenChange(false);
                        // Refrescar datos del servidor en background
                        router.refresh();
                      }
                    } catch (err) {
                      console.error("[ERROR]", err);
                    }
                  }}
                  className="gap-1.5"
                >
                  <CheckCircle2 className="h-4 w-4" />
                  Marcar como completada
                </Button>
              )}
              <Button asChild>
                <Link href={matterHref(item.matter)}>Ver caso</Link>
              </Button>
            </DialogFooter>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

function DetailLine({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="grid grid-cols-[4.5rem_1fr] gap-3 text-sm">
      <span className="text-[11px] text-muted-foreground">{label}</span>
      <span className="min-w-0 text-foreground">{value}</span>
    </div>
  );
}

function Stat({
  label,
  value,
  color,
  icon
}: {
  label: string;
  value: number;
  color: string;
  icon: React.ReactNode;
}) {
  return (
    <div className="ll-surface px-4 py-3.5">
      <div className="flex items-center gap-1.5">
        <span style={{ color }}>{icon}</span>
        <span className="text-[11px] text-muted-foreground">{label}</span>
      </div>
      <div className="ll-stat mt-3 text-[24px] leading-none text-foreground">
        {value}
      </div>
    </div>
  );
}

function dateKey(d: Date) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function formatTime(value: Date) {
  return new Date(value).toLocaleTimeString("es-AR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  });
}

function formatFullDate(value: Date) {
  return new Date(value).toLocaleDateString("es-AR", {
    year: "numeric",
    month: "long",
    day: "numeric",
    weekday: "long"
  });
}

function formatMonthDay(value: Date) {
  return new Date(value).toLocaleDateString("es-AR", {
    month: "2-digit",
    day: "2-digit"
  });
}

function formatProcedureLabel(value: string) {
  return procedureTypeLabel[value as keyof typeof procedureTypeLabel] ?? value;
}

function priorityLabel(value: number) {
  if (value >= 2) return "Urgente";
  if (value === 1) return "Alta";
  return "Normal";
}

function displaySubject(item: ScheduleItem) {
  return item.clientName ?? item.matter.internalCode;
}